import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../../utils/api';

export default function RoutineBuilderPage() {
  const navigate = useNavigate();
  const [restaurants, setRestaurants] = useState([]);
  const [selectedRest, setSelectedRest] = useState(null);
  const [selectedItems, setSelectedItems] = useState([]);
  const [hour, setHour] = useState(8);
  const [minute, setMinute] = useState(0);
  const [ampm, setAmpm] = useState('AM');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    // Fetch all active restaurants
    api.get('/restaurants').then(res => {
      setRestaurants(res.data);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const selectRestaurant = async (rest) => {
    setSelectedRest(rest);
    setSelectedItems([]); // reset items
    try {
      const res = await api.get(`/restaurants/${rest._id}`);
      setSelectedRest(res.data); // getting full restaurant with menu
    } catch {}
  };

  const toggleItem = (item) => {
    if (selectedItems.find(i => i.name === item.name)) {
      setSelectedItems(selectedItems.filter(i => i.name !== item.name));
    } else {
      if (selectedItems.length >= 10) return toast.error('You can select up to 10 items for a routine.');
      setSelectedItems([...selectedItems, { name: item.name, price: item.price, category: item.category, qty: 1 }]);
    }
  };

  const saveRoutine = async () => {
    if (!selectedRest) return toast.error('Please select a restaurant.');
    if (selectedItems.length === 0) return toast.error('Please select at least 1 item.');

    const timeToSave = `${hour < 10 ? '0'+hour : hour}:${minute < 10 ? '0'+minute : minute} ${ampm}`;

    setSaving(true);
    try {
      await api.post('/routines', {
        restaurantId: selectedRest._id,
        triggerTime: timeToSave,
        items: selectedItems
      });
      toast.success('Your Zero-Click Predictive Routine has been saved!');
      navigate(-1);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to save routine');
    } finally {
      setSaving(false);
    }
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center bg-[#f8f9fa]">
      <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-purple-600"></div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f8f9fa] pb-20">
      <div className="bg-purple-600 text-center py-12 px-6 rounded-b-[40px] shadow-lg mb-8 text-white">
        <div className="text-6xl mb-3">🔮</div>
        <h1 className="text-3xl font-extrabold mb-1">Predictive Orders</h1>
        <p className="text-purple-200">We will build a custom cart automatically everyday.</p>
      </div>

      <div className="max-w-2xl mx-auto px-4">
        {!selectedRest ? (
          <div>
            <h2 className="text-xl font-bold text-gray-800 mb-6 px-1">Step 1: Choose a Restaurant</h2>
            <div className="space-y-3">
              {restaurants.map(r => (
                <button 
                  key={r._id} 
                  onClick={() => selectRestaurant(r)}
                  className="w-full text-left bg-white p-5 rounded-2xl shadow-sm border border-gray-100 hover:shadow-md transition hover:border-purple-200"
                >
                  <span className="text-lg font-bold text-gray-800 flex items-center gap-3">
                    <span className="text-2xl">🍽️</span> {r.name}
                  </span>
                </button>
              ))}
            </div>
          </div>
        ) : (
          <div className="animate-fade-in">
            <button 
              onClick={() => setSelectedRest(null)}
              className="text-purple-600 font-bold mb-6 hover:text-purple-800 transition px-1"
            >
              ← Change Restaurant
            </button>

            <h2 className="text-xl font-bold text-gray-800 mb-4 px-1">Step 2: Select Items (Max 10)</h2>
            <div className="space-y-3 mb-8">
              {selectedRest.menu && selectedRest.menu.length > 0 ? (
                selectedRest.menu.map(item => {
                  const isSelected = !!selectedItems.find(i => i.name === item.name);
                  return (
                    <button 
                      key={item._id} 
                      onClick={() => toggleItem(item)}
                      className={`w-full flex justify-between items-center p-4 rounded-xl transition shadow-sm border ${
                        isSelected ? 'bg-purple-600 text-white border-purple-600 shadow-md transform scale-[1.01]' : 'bg-white text-gray-800 border-gray-100 hover:border-purple-300'
                      }`}
                    >
                      <div className="text-left">
                        <h3 className={`text-base font-bold ${isSelected ? 'text-white' : 'text-gray-800'}`}>{item.name}</h3>
                        <p className={`text-sm mt-1 ${isSelected ? 'text-purple-200' : 'text-gray-500'}`}>₹{item.price}</p>
                      </div>
                      {isSelected && <span className="text-xl">✅</span>}
                    </button>
                  );
                })
              ) : (
                <p className="text-gray-500 p-4">No menu items available.</p>
              )}
            </div>

            <h2 className="text-xl font-bold text-gray-800 mb-4 px-1">Step 3: Trigger Time</h2>
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 mb-10 flex flex-wrap justify-center items-center gap-6 md:gap-10">
              <div className="flex flex-col items-center">
                <button onClick={() => setHour(h => h === 12 ? 1 : h + 1)} className="p-2 text-purple-600 hover:text-purple-800 rounded-full hover:bg-purple-50 transition text-2xl">▲</button>
                <div className="text-5xl font-extrabold text-gray-800 py-2 w-16 text-center">{hour < 10 ? '0'+hour : hour}</div>
                <button onClick={() => setHour(h => h === 1 ? 12 : h - 1)} className="p-2 text-purple-600 hover:text-purple-800 rounded-full hover:bg-purple-50 transition text-2xl">▼</button>
              </div>
              <div className="text-5xl font-extrabold text-gray-800 pb-2">:</div>
              <div className="flex flex-col items-center">
                <button onClick={() => setMinute(m => m >= 59 ? 0 : m + 1)} className="p-2 text-purple-600 hover:text-purple-800 rounded-full hover:bg-purple-50 transition text-2xl">▲</button>
                <div className="text-5xl font-extrabold text-gray-800 py-2 w-16 text-center">{minute < 10 ? '0'+minute : minute}</div>
                <button onClick={() => setMinute(m => m <= 0 ? 59 : m - 1)} className="p-2 text-purple-600 hover:text-purple-800 rounded-full hover:bg-purple-50 transition text-2xl">▼</button>
              </div>
              <div className="flex flex-col gap-2 ml-4">
                <button 
                  onClick={() => setAmpm('AM')} 
                  className={`py-3 px-6 rounded-xl font-bold border transition ${ampm === 'AM' ? 'bg-purple-600 text-white border-purple-600' : 'bg-white text-gray-600 border-gray-200 hover:border-purple-300'}`}
                >
                  AM
                </button>
                <button 
                  onClick={() => setAmpm('PM')} 
                  className={`py-3 px-6 rounded-xl font-bold border transition ${ampm === 'PM' ? 'bg-purple-600 text-white border-purple-600' : 'bg-white text-gray-600 border-gray-200 hover:border-purple-300'}`}
                >
                  PM
                </button>
              </div>
            </div>

            <button 
              onClick={saveRoutine} 
              disabled={saving}
              className={`w-full py-4 rounded-xl shadow-xl shadow-purple-600/30 font-extrabold text-lg text-white transition flex justify-center items-center ${
                saving ? 'bg-purple-400 cursor-not-allowed' : 'bg-purple-600 hover:bg-purple-700 hover:-translate-y-1'
              }`}
            >
              {saving ? <div className="animate-spin rounded-full h-6 w-6 border-t-2 border-white"></div> : 'Save Routine'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
